from __future__ import annotations

import hashlib
import json
import unicodedata
from typing import Any, Mapping


GENESIS: str = "GENESIS"


def normalize_key(s: str) -> str:
    return unicodedata.normalize("NFC", s)


def canonical_bytes(line: Mapping[str, Any]) -> bytes:
    return json.dumps(
        line,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    ).encode("utf-8")


def line_hash(prev_hash: str, line: Mapping[str, Any]) -> str:
    stripped: dict[str, Any] = {}
    for k, v in line.items():
        if k == "hash" or k == "prev_hash":
            continue
        stripped[k] = v
    payload = (prev_hash + "|" + canonical_bytes(stripped).decode("utf-8")).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()

from __future__ import annotations

import os
import tempfile
from pathlib import Path
from typing import Iterable, List


def read_lines(path: Path | str) -> List[bytes]:
    p = Path(path)
    if not p.exists():
        raise FileNotFoundError(str(p))
    raw = p.read_bytes()
    if raw == b"":
        return []
    lines = raw.split(b"\n")
    if lines and lines[-1] == b"":
        lines = lines[:-1]
    return lines


def write_atomic(path: Path | str, lines: Iterable[bytes]) -> None:
    p = Path(path)
    parent = p.parent
    parent.mkdir(parents=True, exist_ok=True)
    fd, tmp_path = tempfile.mkstemp(
        prefix=".ledgerlock.",
        suffix=".tmp",
        dir=str(parent),
    )
    try:
        with os.fdopen(fd, "wb") as f:
            for line in lines:
                if not line.endswith(b"\n"):
                    f.write(line + b"\n")
                else:
                    f.write(line)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp_path, str(p))
    except BaseException:
        try:
            os.unlink(tmp_path)
        except FileNotFoundError:
            pass
        raise

from __future__ import annotations

import json
import os
import threading
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Iterable, Iterator, List, Optional, Sequence, Tuple, Union

from . import format, store


class ConflictError(Exception):
    def __init__(
        self,
        key: str,
        incoming_rid: str,
        committed_rid: str,
        batch_index: Optional[int] = None,
    ) -> None:
        self.key = key
        self.incoming_rid = incoming_rid
        self.committed_rid = committed_rid
        self.batch_index = batch_index
        idx = "" if batch_index is None else f" (batch_index={batch_index})"
        super().__init__(
            f"conflict on key {key!r}: incoming rid {incoming_rid!r} "
            f"!= committed rid {committed_rid!r}{idx}"
        )


Op = str
Key = str
Value = Any
Rid = str
Ts = int

PutTuple = Tuple[Op, Key, Value, Rid, Ts]
DeleteTuple = Tuple[Op, Key, Rid, Ts]
MutationTuple = Union[PutTuple, DeleteTuple]

AppendResult = dict


def _line_bytes(line: dict) -> bytes:
    return format.canonical_bytes(line) + b"\n"


def _strip_hash_fields(line: dict) -> dict:
    out = {}
    for k, v in line.items():
        if k == "hash" or k == "prev_hash":
            continue
        out[k] = v
    return out


def _parse_and_strip(raw: bytes) -> dict:
    obj = json.loads(raw.decode("utf-8"))
    return obj


class Ledger:
    def __init__(self, path: Path | str) -> None:
        self._path = Path(path)
        self._lock = threading.Lock()
        self._committed: dict[str, dict] = {}
        self._tail_hash: str = format.GENESIS
        self._load_from_disk()

    @property
    def path(self) -> Path:
        return self._path

    def _load_from_disk(self) -> None:
        try:
            lines = store.read_lines(self._path)
        except FileNotFoundError:
            return
        prev_hash = "GENESIS"
        last_line: Optional[dict] = None
        committed: dict[str, dict] = {}
        for raw in lines:
            obj = json.loads(raw.decode("utf-8"))
            stripped = _strip_hash_fields(obj)
            expected = format.line_hash(prev_hash, stripped)
            if obj.get("hash") != expected:
                prev_hash = obj.get("hash", prev_hash)
                last_line = obj
                continue
            prev_hash = obj["hash"]
            last_line = obj
            nfc_key = obj["key"]
            committed[nfc_key] = obj
        self._committed = committed
        self._tail_hash = prev_hash

    def _append_line_locked(self, line: dict) -> None:
        line["prev_hash"] = self._tail_hash
        stripped = _strip_hash_fields(line)
        line["hash"] = format.line_hash(self._tail_hash, stripped)
        payload = _line_bytes(line)
        parent = self._path.parent
        parent.mkdir(parents=True, exist_ok=True)
        with open(self._path, "ab") as f:
            f.write(payload)
            f.flush()
            os.fsync(f.fileno())
        self._tail_hash = line["hash"]
        self._committed[line["key"]] = line

    def append(self, op: MutationTuple) -> AppendResult:
        op_name = op[0]
        if op_name == "put":
            _, key, value, rid, ts = op
            nfc_key = format.normalize_key(key)
            if nfc_key == "":
                raise ValueError("empty key after NFC normalization")
        elif op_name == "delete":
            _, key, rid, ts = op
            nfc_key = format.normalize_key(key)
            if nfc_key == "":
                raise ValueError("empty key after NFC normalization")
        else:
            raise ValueError(f"unknown op {op_name!r}")

        with self._lock:
            existing = self._committed.get(nfc_key)
            if existing is not None:
                committed_rid = existing.get("id", "")
                if committed_rid == rid:
                    return {
                        "line": dict(existing),
                        "replayed": True,
                        "committed": False,
                    }
                raise ConflictError(
                    key=nfc_key,
                    incoming_rid=rid,
                    committed_rid=committed_rid,
                    batch_index=None,
                )
            if op_name == "put":
                line = {
                    "op": "put",
                    "key": nfc_key,
                    "value": value,
                    "ts": ts,
                    "id": rid,
                }
            else:
                line = {
                    "op": "delete",
                    "key": nfc_key,
                    "ts": ts,
                    "id": rid,
                }
            self._append_line_locked(line)
            return {"line": dict(line), "replayed": False, "committed": True}

    def apply_batch(self, ops: Sequence[MutationTuple]) -> List[AppendResult]:
        parsed: List[tuple] = []
        for idx, op in enumerate(ops):
            op_name = op[0]
            if op_name == "put":
                _, key, value, rid, ts = op
                nfc_key = format.normalize_key(key)
                if nfc_key == "":
                    raise ValueError("empty key after NFC normalization")
                parsed.append((idx, nfc_key, rid, "put", (op_name, nfc_key, value, rid, ts)))
            elif op_name == "delete":
                _, key, rid, ts = op
                nfc_key = format.normalize_key(key)
                if nfc_key == "":
                    raise ValueError("empty key after NFC normalization")
                parsed.append((idx, nfc_key, rid, "delete", (op_name, nfc_key, rid, ts)))
            else:
                raise ValueError(f"unknown op {op_name!r}")

        with self._lock:
            committed_view = dict(self._committed)
            new_lines: List[dict] = []
            replay_results: List[tuple] = []
            next_tail_hash = self._tail_hash
            for idx, nfc_key, rid, op_kind, normalized in parsed:
                existing = committed_view.get(nfc_key)
                if existing is not None:
                    committed_rid = existing.get("id", "")
                    if committed_rid == rid:
                        replay_results.append((idx, existing))
                        continue
                    raise ConflictError(
                        key=nfc_key,
                        incoming_rid=rid,
                        committed_rid=committed_rid,
                        batch_index=idx,
                    )
                if op_kind == "put":
                    line = {
                        "op": "put",
                        "key": nfc_key,
                        "value": normalized[2],
                        "ts": normalized[4],
                        "id": rid,
                    }
                else:
                    line = {
                        "op": "delete",
                        "key": nfc_key,
                        "ts": normalized[3],
                        "id": rid,
                    }
                line["prev_hash"] = next_tail_hash
                stripped = _strip_hash_fields(line)
                line["hash"] = format.line_hash(next_tail_hash, stripped)
                committed_view[nfc_key] = line
                new_lines.append(line)
                next_tail_hash = line["hash"]

            if not new_lines and not replay_results:
                return []

            if new_lines:
                self._write_atomic_with_lines(new_lines)

            self._committed = committed_view
            self._tail_hash = next_tail_hash

            results: List[AppendResult] = []
            replay_iter = iter(replay_results)
            new_iter = iter(new_lines)
            for idx, _nfc_key, _rid, _op_kind, _norm in parsed:
                replay_match = next((r for r in replay_iter if r[0] == idx), None)
                if replay_match is not None:
                    results.append(
                        {"line": dict(replay_match[1]), "replayed": True, "committed": False}
                    )
                    continue
                line_match = next((n for n in new_iter if n.get("id") == _rid and n.get("key") == _nfc_key), None)
                if line_match is None:
                    line_match = next(new_iter)
                results.append({"line": dict(line_match), "replayed": False, "committed": True})
            return results

    def _write_atomic_with_lines(self, new_lines: List[dict]) -> None:
        try:
            existing = store.read_lines(self._path)
        except FileNotFoundError:
            existing = []
        all_lines: List[bytes] = list(existing)
        for line in new_lines:
            all_lines.append(_line_bytes(line))
        store.write_atomic(self._path, all_lines)

    def verify(self) -> dict:
        try:
            lines = store.read_lines(self._path)
        except FileNotFoundError:
            raise
        prev = "GENESIS"
        for i, raw in enumerate(lines):
            try:
                obj = json.loads(raw.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError):
                return {"ok": False, "first_bad_index": i}
            stripped = _strip_hash_fields(obj)
            expected = format.line_hash(prev, stripped)
            if obj.get("prev_hash") != prev or obj.get("hash") != expected:
                return {"ok": False, "first_bad_index": i}
            prev = obj["hash"]
        return {"ok": True, "first_bad_index": None}

    def snapshot(self) -> dict:
        try:
            lines = store.read_lines(self._path)
        except FileNotFoundError:
            return {}
        state: dict[str, Any] = {}
        for raw in lines:
            obj = json.loads(raw.decode("utf-8"))
            key = obj["key"]
            op = obj["op"]
            if op == "put":
                state[key] = obj.get("value")
            elif op == "delete":
                state.pop(key, None)
        ordered_keys = sorted(state.keys())
        ordered: dict[str, Any] = {}
        for k in ordered_keys:
            ordered[k] = state[k]
        return ordered

    def repair_tail(self) -> dict:
        try:
            raw_bytes = self._path.read_bytes()
        except FileNotFoundError:
            raise
        if raw_bytes == b"":
            verdict = self.verify()
            if verdict["ok"]:
                return {"repaired": False, "ok": True, "first_bad_index": None}
            return {"repaired": False, **verdict}

        lines = raw_bytes.split(b"\n")
        if lines and lines[-1] == b"":
            lines = lines[:-1]

        verdict = self._verify_lines(lines)
        if verdict["ok"]:
            return {"repaired": False, "ok": True, "first_bad_index": None}

        first_bad = verdict["first_bad_index"]
        if first_bad is None or first_bad != len(lines) - 1:
            return {"repaired": False, **verdict}

        try:
            json.loads(lines[-1].decode("utf-8"))
            last_parses = True
        except (UnicodeDecodeError, json.JSONDecodeError):
            last_parses = False

        if not last_parses:
            trimmed = lines[:-1]
            new_verdict = self._verify_lines(trimmed)
            if new_verdict["ok"]:
                rebuilt = b"\n".join(trimmed) + b"\n"
                store.write_atomic(self._path, trimmed)
                self._load_from_disk()
                return {"repaired": True, "ok": True, "first_bad_index": None, "removed": first_bad}
            return {"repaired": False, **new_verdict}

        return {"repaired": False, **verdict}

    def _verify_lines(self, lines: List[bytes]) -> dict:
        prev = "GENESIS"
        for i, raw in enumerate(lines):
            try:
                obj = json.loads(raw.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError):
                return {"ok": False, "first_bad_index": i}
            stripped = _strip_hash_fields(obj)
            expected = format.line_hash(prev, stripped)
            if obj.get("prev_hash") != prev or obj.get("hash") != expected:
                return {"ok": False, "first_bad_index": i}
            prev = obj["hash"]
        return {"ok": True, "first_bad_index": None}

    def close(self) -> None:
        pass

    def __enter__(self) -> "Ledger":
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        self.close()

