from __future__ import annotations

import argparse
import json
import os
import sys
from pathlib import Path
from typing import Any, Sequence

from . import format as _format
from .ledger import ConflictError, Ledger


EXIT_OK = 0
EXIT_USAGE = 2
EXIT_IO = 3
EXIT_CONFLICT = 4
EXIT_CORRUPTION = 5


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="ledgerlock",
        description="Append-only tamper-evident key/value ledger.",
    )
    sub = parser.add_subparsers(dest="command")
    sub.required = True

    p_verify = sub.add_parser("verify", help="verify the ledger end-to-end")
    p_verify.add_argument("ledger")

    p_snapshot = sub.add_parser("snapshot", help="write a deterministic snapshot to --out")
    p_snapshot.add_argument("ledger")
    p_snapshot.add_argument("--out", required=True)

    p_apply = sub.add_parser("apply", help="apply an atomic batch from --batch to the ledger")
    p_apply.add_argument("ledger")
    p_apply.add_argument("--batch", required=True)

    p_repair = sub.add_parser("repair-tail", help="strip a truncated final line if repairable")
    p_repair.add_argument("ledger")

    return parser


def _snapshot_bytes(state: dict) -> bytes:
    return (
        json.dumps(state, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        + b"\n"
    )


def _read_batch(path: Path) -> list:
    with open(path, "rb") as f:
        data = f.read()
    obj = json.loads(data.decode("utf-8"))
    if not isinstance(obj, list):
        raise ValueError("batch file must contain a JSON array")
    return obj


def _cmd_verify(ledger_path: Path) -> int:
    ledger = Ledger(ledger_path)
    verdict = ledger.verify()
    if not verdict["ok"]:
        sys.stderr.write(
            f"verify corrupt: first_bad_index={verdict.get('first_bad_index')}\n"
        )
        return EXIT_CORRUPTION
    sys.stderr.write("verify ok\n")
    return EXIT_OK


def _cmd_snapshot(ledger_path: Path, out_path: Path) -> int:
    ledger = Ledger(ledger_path)
    state = ledger.snapshot()
    out_path.parent.mkdir(parents=True, exist_ok=True)
    payload = _snapshot_bytes(state)
    with open(out_path, "wb") as f:
        f.write(payload)
        f.flush()
        os.fsync(f.fileno())
    sys.stderr.write(f"snapshot wrote {out_path}\n")
    return EXIT_OK


def _cmd_apply(ledger_path: Path, batch_path: Path) -> int:
    raw_ops = _read_batch(batch_path)
    ops = []
    for item in raw_ops:
        if not isinstance(item, list):
            raise ValueError("batch elements must be arrays")
        ops.append(tuple(item))
    ledger = Ledger(ledger_path)
    results = ledger.apply_batch(ops)
    appended = sum(1 for r in results if r.get("committed"))
    sys.stderr.write(f"apply appended {appended} lines\n")
    return EXIT_OK


def _cmd_repair(ledger_path: Path) -> int:
    ledger = Ledger(ledger_path)
    verdict = ledger.repair_tail()
    if verdict.get("ok") and verdict.get("repaired"):
        sys.stderr.write(f"repair-tail removed 1 truncated line\n")
        return EXIT_OK
    if verdict.get("ok") and not verdict.get("repaired"):
        sys.stderr.write("repair-tail no-op: chain clean\n")
        return EXIT_OK
    sys.stderr.write(
        f"repair-tail corrupt: first_bad_index={verdict.get('first_bad_index')}\n"
    )
    return EXIT_CORRUPTION


def _exit_for_exception(exc: BaseException) -> int:
    if isinstance(exc, ConflictError):
        idx = "" if exc.batch_index is None else f" batch_index={exc.batch_index}"
        sys.stderr.write(f"conflict on key {exc.key!r}: rid {exc.incoming_rid!r} != committed {exc.committed_rid!r}{idx}\n")
        return EXIT_CONFLICT
    if isinstance(exc, FileNotFoundError):
        sys.stderr.write(f"io error: file not found: {exc}\n")
        return EXIT_IO
    if isinstance(exc, (PermissionError, IsADirectoryError, NotADirectoryError)):
        sys.stderr.write(f"io error: {exc}\n")
        return EXIT_IO
    if isinstance(exc, OSError):
        sys.stderr.write(f"io error: {exc}\n")
        return EXIT_IO
    if isinstance(exc, (ValueError, TypeError)):
        sys.stderr.write(f"usage error: {exc}\n")
        return EXIT_USAGE
    sys.stderr.write(f"unexpected error: {exc}\n")
    return EXIT_USAGE


def main(argv: Sequence[str] | None = None) -> int:
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as e:
        code = e.code if isinstance(e.code, int) else 2
        if code not in (0, 2):
            return EXIT_USAGE
        return code if code == 0 else EXIT_USAGE

    try:
        if args.command == "verify":
            return _cmd_verify(Path(args.ledger))
        if args.command == "snapshot":
            return _cmd_snapshot(Path(args.ledger), Path(args.out))
        if args.command == "apply":
            return _cmd_apply(Path(args.ledger), Path(args.batch))
        if args.command == "repair-tail":
            return _cmd_repair(Path(args.ledger))
    except SystemExit:
        raise
    except BaseException as exc:
        return _exit_for_exception(exc)

    sys.stderr.write("unknown subcommand\n")
    return EXIT_USAGE


if __name__ == "__main__":
    raise SystemExit(main())

import json
import unittest

from ledgerlock import format


class FormatCanonicalBytesTests(unittest.TestCase):
    def test_canonical_bytes_simple(self):
        line = {"op": "put", "key": "k", "value": "v", "ts": 100, "id": "r"}
        expected = json.dumps(
            line, sort_keys=True, separators=(",", ":"), ensure_ascii=False
        ).encode("utf-8")
        self.assertEqual(format.canonical_bytes(line), expected)

    def test_canonical_bytes_equal_dicts_byte_identical(self):
        a = {"op": "put", "key": "k", "value": "v", "ts": 1, "id": "r"}
        b = {"op": "put", "key": "k", "value": "v", "ts": 1, "id": "r"}
        self.assertEqual(format.canonical_bytes(a), format.canonical_bytes(b))

    def test_canonical_bytes_non_ascii_utf8_literal(self):
        line = {"k": "é"}
        result = format.canonical_bytes(line)
        self.assertIn(b"\xc3\xa9", result)
        self.assertNotIn(b"\\u00e9", result)
        self.assertEqual(format.canonical_bytes(line), result)

    def test_canonical_bytes_insertion_order_independent(self):
        a = {"a": 1, "b": 2, "c": 3}
        b = {"c": 3, "b": 2, "a": 1}
        self.assertEqual(format.canonical_bytes(a), format.canonical_bytes(b))

    def test_genesis_literal(self):
        self.assertEqual(format.GENESIS, "GENESIS")
        self.assertEqual(len(format.GENESIS), 7)
        self.assertNotEqual(format.GENESIS, "0" * 64)

    def test_canonical_bytes_round_trip(self):
        original = {"a": 1, "b": "é", "c": [1, 2, 3]}
        first = format.canonical_bytes(original)
        reloaded = json.loads(first.decode("utf-8"))
        second = format.canonical_bytes(reloaded)
        self.assertEqual(first, second)


class FormatLineHashTests(unittest.TestCase):
    def test_returns_64_lowercase_hex(self):
        h = format.line_hash(format.GENESIS, {"op": "put", "key": "k"})
        self.assertEqual(len(h), 64)
        self.assertTrue(all(c in "0123456789abcdef" for c in h))

    def test_different_prev_hash_gives_different_result(self):
        line = {"op": "put", "key": "k"}
        self.assertNotEqual(
            format.line_hash(format.GENESIS, line),
            format.line_hash("0" * 64, line),
        )

    def test_ignores_existing_hash_fields(self):
        line_with = {"op": "put", "key": "k", "hash": "deadbeef", "prev_hash": "f00d"}
        line_without = {"op": "put", "key": "k", "hash": "x", "prev_hash": "y"}
        self.assertEqual(
            format.line_hash(format.GENESIS, line_with),
            format.line_hash(format.GENESIS, line_without),
        )

    def test_deterministic(self):
        line = {"op": "put", "key": "k"}
        self.assertEqual(
            format.line_hash(format.GENESIS, line),
            format.line_hash(format.GENESIS, line),
        )

    def test_genesis_accepted(self):
        h = format.line_hash(format.GENESIS, {"op": "put", "key": "k"})
        self.assertIsInstance(h, str)
        self.assertEqual(len(h), 64)


class FormatNormalizeKeyTests(unittest.TestCase):
    def test_normalize_passthrough(self):
        self.assertEqual(format.normalize_key("hello"), "hello")

    def test_normalize_nfc(self):
        self.assertEqual(format.normalize_key("\u00e9"), "\u00e9")
        self.assertEqual(format.normalize_key("e\u0301"), "\u00e9")
        self.assertEqual(format.normalize_key("\u00e9"), format.normalize_key("e\u0301"))


if __name__ == "__main__":
    unittest.main()

